<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>人民日报 - 2025年1月9日 第5版</title>
    <style>
        :root {
            --primary-red: #d92323;
            --text-main: #222;
            --bg-grey: #f5f5f5;
            --border-grey: #ccc;
        }
        body {
            font-family: 'SimSun', serif;
            color: var(--text-main);
            margin: 0;
            padding: 20px;
            background-color: #fff;
            display: flex;
            justify-content: center;
        }
        .page-container {
            width: 1300px;
            background: #fff;
        }
        /* Header Styles */
        .header {
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            border-bottom: 3px solid var(--primary-red);
            padding-bottom: 10px;
            margin-bottom: 20px;
        }
        .header-logo {
            font-family: 'SimHei', sans-serif;
            font-size: 48px;
            font-weight: bold;
            letter-spacing: 10px;
        }
        .header-meta {
            display: flex;
            align-items: baseline;
            gap: 20px;
            font-family: 'SimHei', sans-serif;
        }
        .header-date {
            font-size: 16px;
        }
        .header-page-num {
            font-size: 48px;
            font-weight: bold;
            line-height: 0.8;
        }
        .header-page-name {
            font-size: 28px;
            font-weight: bold;
        }

        /* Layout Grid */
        .main-layout {
            display: grid;
            grid-template-columns: 850px 1fr;
            gap: 30px;
        }
        .left-pane {
            display: flex;
            flex-direction: column;
        }
        .right-pane {
            border-left: 1px solid var(--border-grey);
            padding-left: 30px;
            display: flex;
            flex-direction: column;
        }

        /* Common Elements */
        .section-marker {
            color: var(--primary-red);
            font-family: 'SimHei', sans-serif;
            font-size: 18px;
            font-weight: bold;
