            margin-bottom: 15px;
        }
        .section-marker .r-icon {
            border: 1px solid var(--primary-red);
            padding: 0 4px;
            margin-right: 8px;
            font-size: 14px;
        }
        .article-title {
            font-family: 'SimHei', sans-serif;
            font-size: 40px;
            font-weight: bold;
            text-align: center;
            margin: 10px 0;
            line-height: 1.2;
        }
        .article-author {
            font-family: 'KaiTi', 'Kaiti SC', serif;
            text-align: center;
            font-size: 16px;
            margin-bottom: 20px;
        }
        .article-divider {
            border-top: 1px solid var(--border-grey);
